// ============================================================ roll-ups ========================================================
// A roll-up has NO case of its own: it is the worst status of every row that concerns it, picked by tag (ops: join / cut / keep; cat: operand kinds or situations), so a row cannot be left out of it by hand.
const kidsOf = (pred) => [...meta.entries()].filter(([, m]) => pred(m)).map(([k]) => k);
